361	// SIMPLE CSV PARSER
362	// ════════════════════════════════════════════════
363	function parseCSV(text) {
364	  const lines = text.trim().split('\n');
365	  const headers = parseLine(lines[0]).map(h => h.trim());
366	  return lines.slice(1).map(line => {
367	    const vals = parseLine(line);
368	    const obj = {};
369	    headers.forEach((h, i) => { obj[h] = (vals[i] || '').trim(); });
370	    return obj;
371	  });
372	}
373	
374	function parseLine(line) {
375	  const result = [];
376	  let cur = '', inQ = false;
377	  for (let i = 0; i < line.length; i++) {
378	    const c = line[i];
379	    if (c === '"') { inQ = !inQ; }
380	    else if (c === ',' && !inQ) { result.push(cur); cur = ''; }
381	    else { cur += c; }
382	  }
383	  result.push(cur);
384	  return result;
385	}
386	
387	function money(n) {
388	  return parseFloat(String(n).replace(/,/g, '')) || 0;
389	}
390	
391	function fmt(n) {
392	  return Math.round(n).toLocaleString('en-US');
393	}
394	
395	function fmtDate(d) {
396	  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
397	  return `${d.getDate()} ${months[d.getMonth()]} ${d.getFullYear()}`;
398	}
