544	    return `<div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;">
545	      <span style="display:inline-block;width:12px;height:12px;border-radius:3px;background:${pmtBg[i]};flex-shrink:0;"></span>
546	      <span style="font-size:.8rem;flex:1;">${k}</span>
547	      <span style="font-size:.78rem;font-weight:600;color:#555;">${pct}%</span>
548	    </div>`;
549	  }).join('');
550	  document.getElementById('paymentLegend').innerHTML = legendHTML;
551	
552	  // ── Stock Alerts ──
553	  const orderNow    = STOCK_DATA.filter(s => s.status === 'Order Now');
554	  const slowMovers  = STOCK_DATA.filter(s => s.status === 'Slow Mover');
555	  const okCount     = STOCK_DATA.filter(s => s.status === 'OK').length;
556	
557	  document.getElementById('stockSummaryBadges').innerHTML =
558	    `<span class="order-now-badge me-1">&#9888; ${orderNow.length} Order Now</span>` +
559	    `<span class="order-now-badge slow-mover-badge me-1">&#8595; ${slowMovers.length} Slow Movers</span>` +
560	    `<span class="order-now-badge ok-badge">&#10003; ${okCount} OK</span>`;
561	
562	  const stockHTML = orderNow.length === 0
563	    ? '<p class="text-muted small mb-0">No urgent stock alerts.</p>'
564	    : orderNow.map(s => `
565	      <div class="stock-item">
566	        <div>
567	          <div class="product-name">${s.name}</div>
568	          <div class="supplier">Supplier: ${s.supplier} &nbsp;|&nbsp; Stockout: ${s.stockoutDate}</div>
569	        </div>
570	        <div class="d-flex align-items-center gap-2">
571	          <span class="qty">QTY: ${s.qty}</span>
572	          <span class="order-now-badge">Order Now</span>
573	        </div>
574	      </div>`).join('');
575	  document.getElementById('stockAlerts').innerHTML = stockHTML;
576	
577	  // ── Transaction Table ──
578	  const pmtBadge = pmt => {
579	    const isCash = pmt === 'CASHNORM';
580	    return `<span class="badge-pmt ${isCash ? 'pmt-cash':'pmt-ins'}">${pmt}</span>`;
581	  };
582	
583	  const tbody = document.getElementById('txnBody');
584	  const rowsHTML = rows.map(r => {
585	    const rev  = money(r['TOTAL']);
586	    const cost = money(r['TOTAL COST']);
587	    const m    = rev > 0 ? ((rev-cost)/rev*100).toFixed(0) : '—';
588	    const time = r['DATE'].split(' ')[1].slice(0,5);
589	    const name = r['PRODUCT NAME'].trim();
590	    const pmt  = (r['CUSTOMER NAME'] || 'CASHNORM').trim();
591	    const mColor = parseFloat(m) < 10 ? 'color:#dc3545;' : parseFloat(m) < 25 ? 'color:#f0a500;' : 'color:#198754;';
592	    return `<tr>
593	      <td>${r['INVOICE ID']}</td>
594	      <td>${time}</td>
595	      <td class="product-cell" title="${name}">${name}</td>
596	      <td style="text-align:right;">${money(r['QUANTITY'])}</td>
597	      <td style="text-align:right;">${fmt(money(r['PRICE']))}</td>
598	      <td style="text-align:right;font-weight:600;">${fmt(rev)}</td>
599	      <td style="text-align:right;color:#6c757d;">${fmt(cost)}</td>
600	      <td style="text-align:right;font-weight:600;${mColor}">${m !== '—' ? m+'%' : '—'}</td>
601	      <td>${pmtBadge(pmt)}</td>
602	    </tr>`;
603	  }).join('');
604	  tbody.innerHTML = rowsHTML;
605	})();
606	</script>
607	</body>
608	</html>
