      <div class="kpi-card profit">
        <div class="label">Gross Profit</div>
        <div class="value" id="kpiProfit">—</div>
        <div class="sub">RWF today</div>
      </div>
    </div>
    <div class="col-6 col-md-4 col-xl">
      <div class="kpi-card margin">
        <div class="label">Profit Margin</div>
        <div class="value" id="kpiMargin">—</div>
        <div class="sub">% of revenue</div>
      </div>
    </div>
    <div class="col-6 col-md-4 col-xl">
      <div class="kpi-card txn">
        <div class="label">Invoices</div>
        <div class="value" id="kpiInvoices">—</div>
        <div class="sub" id="kpiItems">— line items</div>
      </div>
    </div>
  </div>

  <!-- Charts Row -->
  <div class="row g-3 mb-3">
    <!-- Top Products -->
    <div class="col-12 col-lg-7">
      <div class="chart-card">
        <div class="section-title">Top 10 Products by Revenue (RWF)</div>
        <canvas id="chartTopProducts" style="max-height:280px;"></canvas>
      </div>
    </div>
    <!-- Hourly Sales -->
    <div class="col-12 col-lg-5">
      <div class="chart-card">
        <div class="section-title">Sales by Hour</div>
        <canvas id="chartHourly" style="max-height:280px;"></canvas>
      </div>
    </div>
  </div>

  <!-- Payment + Stock Row -->
  <div class="row g-3 mb-3">
    <!-- Payment Methods -->
    <div class="col-12 col-md-4 col-lg-3">
      <div class="chart-card">
        <div class="section-title">Payment Methods</div>
        <canvas id="chartPayment" style="max-height:200px;"></canvas>
        <div id="paymentLegend" class="mt-2"></div>
      </div>
    </div>
    <!-- Stock Alerts -->
    <div class="col-12 col-md-8 col-lg-9">
      <div class="chart-card">
        <div class="section-title d-flex justify-content-between align-items-center">
          <span>&#9888; Stock Alerts — Order Now</span>
          <span id="stockSummaryBadges"></span>
        </div>
        <div id="stockAlerts"></div>
      </div>
    </div>
  </div>

  <!-- Transactions Table -->
  <div class="row g-3">
    <div class="col-12">
      <div class="chart-card">
        <div class="section-title">Today's Transaction Log (<span id="txnCount">0</span> line items)</div>
        <div style="overflow-x:auto; max-height:380px; overflow-y:auto;">
          <table class="table table-hover txn-table mb-0" id="txnTable">
            <thead style="position:sticky;top:0;z-index:1;">
              <tr>
                <th>Invoice</th>
                <th>Time</th>
                <th>Product</th>
                <th style="text-align:right;">Qty</th>
                <th style="text-align:right;">Unit Price</th>
                <th style="text-align:right;">Revenue</th>
                <th style="text-align:right;">Cost</th>
                <th style="text-align:right;">Margin</th>
                <th>Payment</th>
              </tr>
            </thead>
            <tbody id="txnBody"></tbody>
          </table>
        </div>
      </div>
    </div>
  </div>

</div><!-- /container -->

