// ════════════════════════════════════════════════
// SIMPLE CSV PARSER
// ════════════════════════════════════════════════
function parseCSV(text) {
  const lines = text.trim().split('\n');
  const headers = parseLine(lines[0]).map(h => h.trim());
  return lines.slice(1).map(line => {
    const vals = parseLine(line);
    const obj = {};
    headers.forEach((h, i) => { obj[h] = (vals[i] || '').trim(); });
    return obj;
  });
}

function parseLine(line) {
  const result = [];
  let cur = '', inQ = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === '"') { inQ = !inQ; }
    else if (c === ',' && !inQ) { result.push(cur); cur = ''; }
    else { cur += c; }
  }
  result.push(cur);
  return result;
}

function money(n) {
  return parseFloat(String(n).replace(/,/g, '')) || 0;
}

function fmt(n) {
  return Math.round(n).toLocaleString('en-US');
}

function fmtDate(d) {
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  return `${d.getDate()} ${months[d.getMonth()]} ${d.getFullYear()}`;
}

// ════════════════════════════════════════════════
// MAIN
// ════════════════════════════════════════════════
(function() {
  const rows = parseCSV(RAW_CSV);

  // Exclude insurance copayment lines from revenue (they are just patient shares already counted)
  const sales = rows.filter(r => !r['PRODUCT NAME'].includes('INSURANCE COPAYMENT'));

  // ── KPIs ──
  let totalRevenue = 0, totalCost = 0, totalQty = 0;
  sales.forEach(r => {
    totalRevenue += money(r['TOTAL']);
    totalCost    += money(r['TOTAL COST']);
    totalQty     += money(r['QUANTITY']);
  });
  const grossProfit = totalRevenue - totalCost;
  const margin      = totalRevenue > 0 ? (grossProfit / totalRevenue * 100) : 0;
  const uniqueInvoices = new Set(sales.map(r => r['INVOICE ID'])).size;

  document.getElementById('kpiRevenue').textContent  = fmt(totalRevenue) + ' RWF';
  document.getElementById('kpiCost').textContent     = fmt(totalCost)    + ' RWF';
  document.getElementById('kpiProfit').textContent   = fmt(grossProfit)  + ' RWF';
  document.getElementById('kpiMargin').textContent   = margin.toFixed(1) + '%';
  document.getElementById('kpiInvoices').textContent = uniqueInvoices;
  document.getElementById('kpiItems').textContent    = sales.length + ' line items';
  document.getElementById('txnCount').textContent    = rows.length;

  // Report date
  const firstDate = rows[0]['DATE'];
  const d = new Date(firstDate);
  document.getElementById('reportDate').textContent = fmtDate(d);

  // ── Top Products ──
  const prodMap = {};
  sales.forEach(r => {
    const name = r['PRODUCT NAME'].trim();
    prodMap[name] = (prodMap[name] || 0) + money(r['TOTAL']);
  });
  const sorted = Object.entries(prodMap).sort((a,b) => b[1]-a[1]).slice(0,10);
  const topLabels = sorted.map(([n]) => n.length > 28 ? n.slice(0,28)+'…' : n);
  const topValues = sorted.map(([,v]) => v);

  new Chart(document.getElementById('chartTopProducts'), {
    type: 'bar',
    data: {
      labels: topLabels,
      datasets: [{
        label: 'Revenue (RWF)',
        data: topValues,
        backgroundColor: 'rgba(26,122,74,0.82)',
        borderRadius: 4,
      }]
    },
    options: {
      indexAxis: 'y',
      responsive: true,
      maintainAspectRatio: false,
      plugins: { legend: { display: false }, tooltip: {
        callbacks: { label: ctx => ' ' + fmt(ctx.raw) + ' RWF' }
      }},
      scales: {
        x: { ticks: { callback: v => fmt(v/1000)+'K', font:{size:11} }, grid:{color:'#f0f0f0'} },
        y: { ticks: { font:{size:11} } }
      }
    }
  });

  // ── Hourly Sales ──
  const hourMap = {};
  for (let h = 9; h <= 19; h++) hourMap[h] = 0;
  sales.forEach(r => {
    const hr = parseInt(r['DATE'].split(' ')[1].split(':')[0]);
    hourMap[hr] = (hourMap[hr] || 0) + money(r['TOTAL']);
  });
  const hourKeys   = Object.keys(hourMap).sort((a,b)=>+a-+b);
  const hourLabels = hourKeys.map(h => `${h}:00`);
  const hourVals   = hourKeys.map(h => hourMap[h]);

  new Chart(document.getElementById('chartHourly'), {
    type: 'bar',
    data: {
      labels: hourLabels,
      datasets: [{
        label: 'Revenue',
        data: hourVals,
        backgroundColor: hourVals.map(v => v === Math.max(...hourVals) ? '#f0a500' : 'rgba(13,92,54,0.7)'),
        borderRadius: 4,
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: { legend:{display:false}, tooltip:{
        callbacks:{ label: ctx => ' ' + fmt(ctx.raw) + ' RWF' }
      }},
      scales: {
        y: { ticks: { callback: v => fmt(v/1000)+'K', font:{size:11} }, grid:{color:'#f0f0f0'} },
        x: { ticks:{ font:{size:11} } }
      }
    }
  });

  // ── Payment Methods ──
  const pmtMap = {};
  // group by invoice to avoid double-counting multi-item invoices
  const invPmt = {};
  const invRev = {};
  rows.forEach(r => {
    const id  = r['INVOICE ID'];
    const pmt = r['CUSTOMER NAME'] || 'CASHNORM';
    invPmt[id] = pmt;
    invRev[id] = (invRev[id] || 0) + money(r['TOTAL']);
  });
  Object.entries(invRev).forEach(([id, rev]) => {
    const pmt = invPmt[id];
    pmtMap[pmt] = (pmtMap[pmt] || 0) + rev;
  });

  const pmtColors = { CASHNORM:'#1a7a4a', SANLAM:'#0d6efd', RAMA:'#6f42c1', PRIME:'#f0a500' };
  const pmtLabels = Object.keys(pmtMap);
  const pmtVals   = pmtLabels.map(k => pmtMap[k]);
  const pmtBg     = pmtLabels.map(k => pmtColors[k] || '#888');

  new Chart(document.getElementById('chartPayment'), {
    type: 'doughnut',
    data: {
      labels: pmtLabels,
      datasets: [{ data: pmtVals, backgroundColor: pmtBg, borderWidth: 2 }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: { display: false },
        tooltip: { callbacks: { label: ctx => ` ${ctx.label}: ${fmt(ctx.raw)} RWF` } }
      },
      cutout: '62%'
    }
  });

  // Custom legend
  const legendHTML = pmtLabels.map((k,i) => {
    const pct = (pmtVals[i] / pmtVals.reduce((a,b)=>a+b,0) * 100).toFixed(1);
    return `<div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;">
      <span style="display:inline-block;width:12px;height:12px;border-radius:3px;background:${pmtBg[i]};flex-shrink:0;"></span>
      <span style="font-size:.8rem;flex:1;">${k}</span>
      <span style="font-size:.78rem;font-weight:600;color:#555;">${pct}%</span>
    </div>`;
  }).join('');
  document.getElementById('paymentLegend').innerHTML = legendHTML;

  // ── Stock Alerts ──
  const orderNow    = STOCK_DATA.filter(s => s.status === 'Order Now');
  const slowMovers  = STOCK_DATA.filter(s => s.status === 'Slow Mover');
  const okCount     = STOCK_DATA.filter(s => s.status === 'OK').length;

  document.getElementById('stockSummaryBadges').innerHTML =
    `<span class="order-now-badge me-1">&#9888; ${orderNow.length} Order Now</span>` +
    `<span class="order-now-badge slow-mover-badge me-1">&#8595; ${slowMovers.length} Slow Movers</span>` +
    `<span class="order-now-badge ok-badge">&#10003; ${okCount} OK</span>`;

  const stockHTML = orderNow.length === 0
    ? '<p class="text-muted small mb-0">No urgent stock alerts.</p>'
    : orderNow.map(s => `
      <div class="stock-item">
        <div>
          <div class="product-name">${s.name}</div>
          <div class="supplier">Supplier: ${s.supplier} &nbsp;|&nbsp; Stockout: ${s.stockoutDate}</div>
        </div>
        <div class="d-flex align-items-center gap-2">
          <span class="qty">QTY: ${s.qty}</span>
          <span class="order-now-badge">Order Now</span>
        </div>
      </div>`).join('');
  document.getElementById('stockAlerts').innerHTML = stockHTML;

  // ── Transaction Table ──
  const pmtBadge = pmt => {
    const isCash = pmt === 'CASHNORM';
    return `<span class="badge-pmt ${isCash ? 'pmt-cash':'pmt-ins'}">${pmt}</span>`;
  };

  const tbody = document.getElementById('txnBody');
  const rowsHTML = rows.map(r => {
    const rev  = money(r['TOTAL']);
    const cost = money(r['TOTAL COST']);
    const m    = rev > 0 ? ((rev-cost)/rev*100).toFixed(0) : '—';
    const time = r['DATE'].split(' ')[1].slice(0,5);
    const name = r['PRODUCT NAME'].trim();
    const pmt  = (r['CUSTOMER NAME'] || 'CASHNORM').trim();
    const mColor = parseFloat(m) < 10 ? 'color:#dc3545;' : parseFloat(m) < 25 ? 'color:#f0a500;' : 'color:#198754;';
    return `<tr>
      <td>${r['INVOICE ID']}</td>
      <td>${time}</td>
      <td class="product-cell" title="${name}">${name}</td>
      <td style="text-align:right;">${money(r['QUANTITY'])}</td>
      <td style="text-align:right;">${fmt(money(r['PRICE']))}</td>
      <td style="text-align:right;font-weight:600;">${fmt(rev)}</td>
      <td style="text-align:right;color:#6c757d;">${fmt(cost)}</td>
      <td style="text-align:right;font-weight:600;${mColor}">${m !== '—' ? m+'%' : '—'}</td>
      <td>${pmtBadge(pmt)}</td>
    </tr>`;
  }).join('');
  tbody.innerHTML = rowsHTML;
})();
